"use client";

import { ColumnDef } from "@tanstack/react-table";

export const orderColumns: ColumnDef<any>[] = [
  {
    header: "ID",
    accessorKey: "id",
    cell: ({ row }) => <span className="text-xs text-gray-400">{row.original.id.slice(0, 8)}</span>
  },
  {
    header: "Type",
    accessorKey: "type",
    cell: ({ row }) => (
      <span className={`px-2 py-1 rounded text-xs font-bold ${
        row.original.type === "SALE" ? "bg-blue-100 text-blue-700" : "bg-purple-100 text-purple-700"
      }`}>
        {row.original.type}
      </span>
    )
  },
  {
    header: "Entity",
    cell: ({ row }) => {
      const entity = row.original.type === "SALE" ? row.original.customer?.name : row.original.supplier?.name;
      return entity || "—";
    }
  },
  {
    header: "Status",
    accessorKey: "status",
    cell: ({ row }) => (
      <span className={`px-2 py-1 rounded text-xs font-bold ${
        row.original.status === "COMPLETED" ? "bg-green-100 text-green-700" :
        row.original.status === "CANCELLED" ? "bg-red-100 text-red-700" :
        "bg-yellow-100 text-yellow-700"
      }`}>
        {row.original.status}
      </span>
    )
  },
  {
    header: "Amount",
    cell: ({ row }) => `₹${row.original.totalAmount?.toLocaleString() || "0"}`
  },
  {
    header: "Date",
    accessorKey: "createdAt",
    cell: ({ row }) => new Date(row.original.createdAt).toLocaleDateString()
  }
];
